mapper.select:
SELECT sort_order, slot_no, vehicle_no, ab_label, employee_name
FROM hd_route_roster
WHERE roster_month = #{rosterMonth}
  AND route_no = #{routeNo}
ORDER BY sort_order

SELECT employee_name, route_no
FROM hd_route_roster
WHERE roster_month = #{rosterMonth}
  AND route_no <> #{routeNo}
  AND employee_name IS NOT NULL
ORDER BY route_no, sort_order

SELECT COUNT(*)
FROM hd_route_roster
WHERE roster_month = #{rosterMonth}
  AND route_no = #{routeNo}

mapper.delete:
DELETE FROM hd_route_roster
WHERE roster_month = #{rosterMonth}
  AND route_no = #{routeNo}
